/**
 * Terav wordmark — "terav." in outlined Inter 800 with a bronze full stop
 * (brand Direction B, 2026-10-27; guide in dev/active/brand/brand-guide.md).
 * /wordmark.svg is generated by dev/scripts/brand/build-brand-assets.mjs and
 * is the same file the landing nav serves. In running copy write "Terav".
 */
export function Wordmark({ height = 20 }: { height?: number }) {
  return (
    // eslint-disable-next-line @next/next/no-img-element -- static SVG, no optimisation needed
    <img src="/wordmark.svg" alt="Terav" height={height} width={Math.round((height * 5477) / 1405)} className="block" />
  );
}
